<div class="d-flex justify-content-between mb-3"><h4>Purchase Orders</h4><?php if (Auth::can('inventory.purchasing.create')): ?><a class="btn btn-primary" href="<?= url('purchasing/form') ?>"><i class="bi bi-plus-lg"></i> New PO</a><?php endif; ?></div>
<div class="btn-group mb-3 flex-wrap"><?php foreach (['' => 'All', 'draft' => 'Draft', 'submitted' => 'Submitted', 'approved' => 'Approved', 'partial' => 'Partial', 'received' => 'Received', 'cancelled' => 'Cancelled'] as $k => $l): ?><a class="btn btn-sm btn-outline-secondary <?= $st === $k ? 'active' : '' ?>" href="<?= url('purchasing/index', $k ? ['status' => $k] : []) ?>"><?= $l ?></a><?php endforeach; ?></div>
<div class="card"><div class="table-responsive"><table class="table table-sm table-hover mb-0"><thead class="table-light"><tr><th>PO</th><th>Date</th><th>Supplier</th><th class="text-end">Total</th><th>Status</th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><a href="<?= url('purchasing/view', ['id' => $r['id']]) ?>"><?= e($r['po_no']) ?></a></td><td><?= e($r['order_date']) ?></td><td><?= link_supplier($r['supplier_id'], $r['supplier']) ?></td><td class="text-end"><?= e(money($r['total'])) ?></td><td><?= badge($r['status']) ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="5" class="text-center text-muted py-3">No purchase orders.</td></tr><?php endif; ?></tbody></table></div></div>
